args.command:
cd <projeto>/storage/workspaces; python3 - <<'EOF'
p='src/usuarios.ts'; s=open(p).read()
s=s.replace('''export const usuariosPadrao: ReadonlyArray<Usuario> = [
  { id: 1, nome: "Ana", email: "ana@exemplo.com", ativo: true },
  { id: 2, nome: "Bruno", email: "bruno@exemplo.com", ativo: false },
  { id: 3, nome: "Carla", email: "carla@exemplo.com", ativo: true },
];''','''export const usuariosPadrao: ReadonlyArray<Usuario> = Object.freeze([
  Object.freeze({ id: 1, nome: "Ana", email: "ana@exemplo.com", ativo: true }),
  Object.freeze({ id: 2, nome: "Bruno", email: "bruno@exemplo.com", ativo: false }),
  Object.freeze({ id: 3, nome: "Carla", email: "carla@exemplo.com", ativo: true }),
]);''')
open(p,'w').write(s)
p='src/usuarios.test.ts'; s=open(p).read()
s+='''
test("usuariosPadrao não pode ser alterado em tempo de execução", () => {
  const lista = usuariosPadrao as Usuario[];
  assert.throws(() => lista.push({ id: 4, nome: "Davi", email: "davi@exemplo.com", ativo: true }), TypeError);
  assert.throws(() => {
    (lista[1] as { ativo: boolean }).ativo = true;
  }, TypeError);
  assert.equal(usuariosPadrao.length, 3);
  assert.equal(descreverAtivos(usuariosPadrao), "Usuários ativos: Ana, Carla");
});
'''
open(p,'w').write(s)
EOF
npm test 2>&1 | tail -12; git stash -q -- src/usuarios.ts; npm test 2>&1 | grep -E "^# (pass|fail)"; git stash pop -q; git status --short

